run:
() => {
      const G = window.cini; let t = 0;
      while (!G.bot.done && t < 6000) { window.ciniSim(10); t += 10; }
      const best = G.progress.best, keys = Array.from({ length: 30 }, (_, i) => 'L' + (i + 1)).filter((k) => best[k]);
      window.__gateM = { levelsDone: G.bot.levelsDone || 0, solved: keys.length, stars: keys.reduce((a, k) => a + best[k].stars, 0),
        moves: keys.reduce((a, k) => a + best[k].moves, 0), collection: G.progress.collection.length, simSeconds: t, botDone: !!G.bot.done };
    }
